from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = OrderedDict()
        # Track insertion order of keys in the cache
        self.order = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return None
        # Move to end (most recently used)
        self.data[key] = None  # Mark as accessed
        self.order[key]  # Update order position
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            # Key exists - refresh it and mark as accessed
            self.data[key] = value
            self.order[key]  # Update order position
        elif len(self.data) >= self.capacity:
            # Evict the oldest (first) entry
            oldest_key = next(iter(self.order))  # Get the first key in order
            del self.order[oldest_key]
            del self.data[oldest_key]
        self.data[key] = value
        self.order[key]

    def __len__(self):
        return len(self.data)
